"""Analysis-informed test synthesis: turn fuzzer witnesses into Java test classes.

Usage: python synthesis.py WITNESSES [TAINT_REPORT.json ...] > SynthesizedTests.java
"""

import json
import string
import sys
from itertools import groupby

import jpamb

# The generated test class; $checks is one check(...) line per witness
TEMPLATE = string.Template("""\
import java.util.concurrent.*;
import jpamb.utils.CaseContent.ResultType;

/** Generated by synthesis.py: replays fuzzer witnesses and checks their outcomes. */
public class SynthesizedTests {
  static int total = 0, failed = 0;

  // Run a call with a timeout and name its outcome the way JPAMB does
  static String outcome(Runnable call) {
    try {
      CompletableFuture.runAsync(call).get(2, TimeUnit.SECONDS);
      return ResultType.SUCCESS.toString();
    } catch (ExecutionException e) {
      return describe(e.getCause());
    } catch (Exception e) {
      return describe(e); // a TimeoutException means "*"
    }
  }

  static String describe(Throwable t) {
    try {
      return ResultType.fromThrowable(t).toString();
    } catch (RuntimeException e) {
      return t.toString(); // an exception with no JPAMB outcome
    }
  }

  static void check(String expected, String call, Runnable test) {
    String actual = outcome(test);
    boolean pass = actual.equals(expected);
    total++;
    if (!pass) failed++;
    System.out.printf("%s  %-15s  %s%s%n", pass ? "PASS" : "FAIL", expected, call,
        pass ? "" : "  (got " + actual + ")");
  }

  public static void main(String[] args) {
    // Like java -ea: the cases use assert, which is off by default
    ClassLoader.getSystemClassLoader().setDefaultAssertionStatus(true);
$checks
    System.out.printf("%d/%d checks passed%n", total - failed, total);
    System.exit(failed == 0 ? 0 : 1);
  }
}
""")


def load_witnesses(path: str) -> list[jpamb.Case]:
    """Read witnesses: one jpamb.Case per line, the same format as cases.txt."""
    return [jpamb.Case.decode(line) for line in open(path).read().splitlines()]


def java_literal(value: jpamb.case.Value) -> str:
    """Write an input value as Java source code."""
    match value:
        # JSON's escapes are a subset of Java's, and the output is pure ASCII
        case jpamb.case.String() | jpamb.case.Int() | jpamb.case.Boolean():
            return json.dumps(value.value)
        case _:
            raise NotImplementedError(f"No Java literal for {value!r}")


def java_call(case: jpamb.Case) -> str:
    """The Java source that calls the witness's method with its input."""
    method = case.methodid
    args = ", ".join(java_literal(v) for v in case.input.values)
    # Nested classes are A$B in bytecode but A.B in source
    return f"{method.classname.dotted().replace('$', '.')}.{method.extension.name}({args})"


def summary(cases: list[jpamb.Case], report: dict | None) -> str:
    """One line on a method: the taint's verdict, upgraded if the fuzzer found an exploit."""
    taint = report["classification"] if report else "not analysed"
    # In the suite the canary throws an AssertionError, so it marks a working exploit
    status = "vulnerable" if any(case.result == "assertion error" for case in cases) else taint
    sinks = "".join(
        f"; sink {f['taint_sink']} from {', '.join(f['labels'])}"
        for f in (report or {}).get("findings", [])
    )
    return f"== {cases[0].methodid}: {status} (taint: {taint}{sinks})"


def synthesize(witnesses: list[jpamb.Case], reports: dict[str, dict] = {}) -> str:
    """The source of a Java class with one check per witness, grouped by method."""
    lines = []
    # Sorted, so the exploit and the normal input of a method end up together
    for method, group in groupby(sorted(set(witnesses)), key=lambda case: case.methodid):
        cases = list(group)
        lines.append(f"    System.out.println({json.dumps(summary(cases, reports.get(str(method))))});")
        for case in cases:
            call = java_call(case)
            lines.append(f"    check({json.dumps(case.result)}, {json.dumps(call)}, () -> {call});")
    return TEMPLATE.substitute(checks="\n".join(lines))


if __name__ == "__main__":
    reports = [json.load(open(path)) for path in sys.argv[2:]]
    print(synthesize(load_witnesses(sys.argv[1]), {r["entry_method"]: r for r in reports}), end="")
